using AntiDbt.Core;
using AntiDbt.Providers;
using AntiDbt.CloudSpeech;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.WebUtilities;
using Microsoft.Extensions.Logging;
using Microsoft.Net.Http.Headers;
using System.Buffers.Binary;
using System.Diagnostics;
using System.Net.Http.Json;
using System.Net.WebSockets;
using System.Runtime.CompilerServices;
using System.Text;
using System.Text.Json;

static class LocalProtocol
{
    const string Source="Hello local world", Target="你好，本地世界";
    static void Assert(bool value,string why){if(!value)throw new Exception(why);}
    public static async Task<int> RunAsync()
    {
        var builder=WebApplication.CreateBuilder();builder.Logging.ClearProviders();builder.WebHost.UseUrls("http://127.0.0.1:0");await using var app=builder.Build();app.UseWebSockets();
        var errors=new System.Collections.Concurrent.ConcurrentQueue<string>();int wavs=0,writes=0,sockets=0,finalFrames=0;
        app.MapPost("/asr",async ctx=>{try{
            Assert(ctx.Request.Headers.Authorization=="Bearer dummy","ASR auth");var media=MediaTypeHeaderValue.Parse(ctx.Request.ContentType!);var reader=new MultipartReader(HeaderUtilities.RemoveQuotes(media.Boundary).Value!,ctx.Request.Body);bool wav=false,model=false;MultipartSection? part;
            while((part=await reader.ReadNextSectionAsync())!=null){var disposition=ContentDispositionHeaderValue.Parse(part.ContentDisposition!);using var data=new MemoryStream();await part.Body.CopyToAsync(data);var bytes=data.ToArray();var name=HeaderUtilities.RemoveQuotes(disposition.Name).Value;
                if(name=="file"){Assert(bytes.Length>44&&Encoding.ASCII.GetString(bytes,0,4)=="RIFF"&&BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(24))==16000&&BinaryPrimitives.ReadInt16LittleEndian(bytes.AsSpan(22))==1,"WAV16kmono");wav=true;}if(name=="model")model=Encoding.UTF8.GetString(bytes)=="whisper-large-v3-turbo";}
            Assert(wav&&model,"multipart fields");Interlocked.Increment(ref wavs);await ctx.Response.WriteAsJsonAsync(new{text=Source});}catch(Exception e){errors.Enqueue(e.Message);ctx.Response.StatusCode=400;}});
        app.MapPost("/gateway/{action}",async ctx=>{if((string)ctx.Request.RouteValues["action"]! =="write"){using var data=new MemoryStream();await ctx.Request.Body.CopyToAsync(data);Assert(data.Length>0&&data.Length%2==0,"gateway PCM");Interlocked.Increment(ref writes);}await ctx.Response.WriteAsJsonAsync(new{text=Source});});
        app.MapPost("/mt/{id}/{**rest}",async ctx=>{try{
            var id=(string)ctx.Request.RouteValues["id"]!;if(id=="BaiduTranslate"){var form=await ctx.Request.ReadFormAsync();Assert(form["q"]==Source&&form["to"]=="zh"&&(form["from"]=="en"||form["from"]=="auto"),"Baidu pipeline actual languages/text");var expected=Convert.ToHexStringLower(System.Security.Cryptography.MD5.HashData(Encoding.UTF8.GetBytes("dummy-app"+form["q"]+form["salt"]+"dummy")));Assert(form["sign"]==expected,"Baidu pipeline signature");await ctx.Response.WriteAsJsonAsync(new{trans_result=new[]{new{dst=Target}}});return;}using var doc=await JsonDocument.ParseAsync(ctx.Request.Body);var r=doc.RootElement;string text=id switch{"DeepL"=>r.GetProperty("text")[0].GetString()!,"AzureTranslator"=>r[0].GetProperty("Text").GetString()!,"GoogleTranslationBasic"=>r.GetProperty("q").GetString()!,"VolcengineMachineTranslation"=>r.GetProperty("text_list")[0].GetString()!,_=>r.GetProperty("messages")[1].GetProperty("content").GetString()!};Assert(text==Source,"original text preserved");
            if(id=="DeepL")Assert(ctx.Request.Headers.Authorization=="DeepL-Auth-Key dummy","DeepL auth");if(id=="AzureTranslator")Assert(ctx.Request.Headers["Ocp-Apim-Subscription-Key"]=="dummy"&&ctx.Request.Query["api-version"]=="3.0","Azure auth/query");if(id=="GoogleTranslationBasic")Assert(ctx.Request.Query["key"]=="dummy","Google key");if(id=="VolcengineMachineTranslation")Assert(ctx.Request.Headers["X-Api-Key"]=="dummy","Volc auth");if(id is "GroqLlm" or "OpenAiCompatible")Assert(ctx.Request.Headers.Authorization=="Bearer dummy"&&ctx.Request.Path.Value!.EndsWith("chat/completions"),"LLM auth/path");
            object response=id switch{"DeepL"=>new{translations=new[]{new{text=Target}}},"AzureTranslator"=>new[]{new{translations=new[]{new{text=Target}}}},"GoogleTranslationBasic"=>new{data=new{translations=new[]{new{translatedText=Target}}}},"VolcengineMachineTranslation"=>new{code=20000000,data=new{translation_list=new[]{new{translation=Target}}}},_=>new{choices=new[]{new{message=new{content=Target}}}}};await ctx.Response.WriteAsJsonAsync(response);
            }catch(Exception e){errors.Enqueue(e.Message);ctx.Response.StatusCode=400;}});
        app.MapPost("/",async ctx=>{var form=await ctx.Request.ReadFormAsync();Assert(form["SourceLanguage"]=="en"&&form["TargetLanguage"]=="zh"&&form["SourceText"]==Source,"Aliyun pipeline actual parameters");Assert(ctx.Request.Headers.Authorization.ToString().StartsWith("ACS3-HMAC-SHA256"),"Aliyun ACS3");await ctx.Response.WriteAsync(JsonSerializer.Serialize(new{Code=200,Data=new{Translated=Target}}));});app.MapPost("/failure",ctx=>{ctx.Response.StatusCode=401;return Task.CompletedTask;});app.MapPost("/cancel",async ctx=>{try{await Task.Delay(5000,ctx.RequestAborted);}catch(OperationCanceledException){}});
        app.Map("/socket",async ctx=>{try{Assert(ctx.Request.Headers["X-Api-Key"]=="dummy","Volc ASR auth");using var ws=await ctx.WebSockets.AcceptWebSocketAsync();Interlocked.Increment(ref sockets);var config=await Receive(ws,ctx.RequestAborted);Assert(config[1]>>4==1,"configuration frame");using(var doc=JsonDocument.Parse(config.AsMemory(12)))Assert(doc.RootElement.GetProperty("audio").GetProperty("rate").GetInt32()==16000,"audio config");bool sent=false;
            while(true){var frame=await Receive(ws,ctx.RequestAborted);Assert(frame[1]>>4==2,"audio frame");if(BinaryPrimitives.ReadInt32BigEndian(frame.AsSpan(4))<0){Interlocked.Increment(ref finalFrames);await Send(ws,true,true,ctx.RequestAborted);break;}Assert(frame.Length>12,"PCM payload");if(!sent){await Send(ws,false,false,ctx.RequestAborted);await Send(ws,true,false,ctx.RequestAborted);sent=true;}}await ws.CloseOutputAsync(WebSocketCloseStatus.NormalClosure,"",ctx.RequestAborted);
            }catch(Exception e){errors.Enqueue(e.Message);}});
        await app.StartAsync();string address=app.Urls.Single();using var client=new HttpClient(new HttpClientHandler{UseProxy=false,AllowAutoRedirect=false});var checks=new List<object>();int failed=0;
        async Task Check(string name,Func<Task> run){try{await run();checks.Add(new{name,pass=true});}catch(Exception e){failed++;checks.Add(new{name,pass=false,error=e.Message});}}
        var pairs=ProviderDescriptors.Translation.Select(x=>("GroqWhisper",x.Id)).Concat(new[]{("AzureSpeech","AzureTranslator"),("AzureSpeech","DeepL"),("GoogleCloudSpeech","GroqLlm"),("GoogleCloudSpeech","GoogleTranslationBasic"),("VolcengineAsr2","DeepL"),("VolcengineAsr2","BaiduTranslate"),("VolcengineAsr2","VolcengineMachineTranslation")});
        foreach(var (asr,mt) in pairs)await Check(asr+" + "+mt,async()=>{
            var config=ProviderDescriptors.DefaultAsr(asr) with{ApiKey="dummy",Language="en"};Gateway? transport=null;IAsrProvider provider;
            if(asr=="GroqWhisper"){config=config with{Endpoint=address+"/asr",Language="en",Options=new(){["minSegmentMs"]="300",["silenceMs"]="200"}};provider=new GroqWhisperProvider(client);}
            else if(asr=="VolcengineAsr2"){config=config with{Endpoint=address.Replace("http:","ws:")+"/socket",Language="auto"};provider=new VolcengineAsrProvider();}
            else if(asr=="AzureSpeech"){config=config with{Options=new(){["region"]="eastus"}};provider=new AzureSpeechProvider(_=>transport=new(client,address));}
            else{config=config with{Endpoint="",Options=new(){["project"]="local-project",["region"]="global"},Secrets=new(){["serviceAccountJson"]="{\"type\":\"service_account\",\"token_uri\":\"https://oauth2.googleapis.com/token\",\"private_key\":\"dummy\",\"client_email\":\"dummy@local.test\"}"}};provider=new GoogleSpeechProvider(_=>transport=new(client,address));}
            var translation=ProviderDescriptors.DefaultTranslation(mt) with{Endpoint=address+"/mt/"+mt+(mt is "GroqLlm" or "OpenAiCompatible"?"/v1":""),ApiKey="dummy",Model="local-model",DebounceMilliseconds=0};translation=translation with{Options=new(translation.Options){["modelLanguages"]="en,zh-Hans",["appId"]="dummy-app",["region"]="cn-hangzhou"},Secrets=new(){["accessKeyId"]="dummy-access-id"}};ITranslationProvider translator=mt=="BaiduTranslate"?new ValidatedTranslationProvider(translation,new BaiduTranslationProvider(translation,client)):mt=="AliyunMT"?new AliyunTranslationProvider(translation with{Endpoint="https://mt.cn-hangzhou.aliyuncs.com"},new Uri(address)):ProviderCatalog.CreateTranslator(translation);provider=new LanguageAwareAsrProvider(provider);var audio=new Audio();var store=new SubtitleStore();var seen=new List<CaptionSegment>();var states=new List<PipelineState>();store.Changed+=()=>{lock(seen)seen.AddRange(store.Snapshot());};var pipeline=new CaptionPipeline(audio,provider,translator,new(){Asr=config,Translation=translation,TargetLanguage="zh"},store);pipeline.StatusChanged+=s=>states.Add(s.State);
            try{await pipeline.StartAsync();await pipeline.Completion.WaitAsync(TimeSpan.FromSeconds(12));var row=store.Snapshot().Single();Assert(row.SourceText==Source&&row.TranslationText==Target&&row.IsFinal&&row.TranslationError==null&&row.TranslationRevision==row.Revision,"exact final row");lock(seen){int first=seen.FindIndex(x=>x.SourceText==Source&&x.TranslationText.Length==0),last=seen.FindIndex(x=>x.TranslationText==Target);Assert(first>=0&&last>first,"source before translation");Assert(seen.Where(x=>x.TranslationText==Target).All(x=>x.SessionId==row.SessionId&&x.SegmentId==row.SegmentId&&x.TranslationRevision>0&&x.TranslationRevision<=x.Revision),"identity/revision");if(asr!="GroqWhisper")Assert(seen.Any(x=>!x.IsFinal),"partial observed");}Assert(states.Contains(PipelineState.Stopped)&&!states.Contains(PipelineState.Error),"clean finalization");}finally{await pipeline.DisposeAsync();}Assert(audio.Disposed&&(transport==null||transport.Disposed),"clean disposal");});
        await Check("server authentication failure",async()=>{var c=ProviderDescriptors.DefaultTranslation("DeepL") with{Endpoint=address+"/failure",ApiKey="dummy"};try{await new HttpTranslationProvider(c,client).TranslateAsync(new(1,"f",1,Source,"en","zh",[]),default);throw new Exception("expected failure");}catch(ProviderException e){Assert(e.Kind==ProviderErrorKind.Authentication,"authentication classification");}});
        await Check("server cancellation",async()=>{var c=ProviderDescriptors.DefaultTranslation("DeepL") with{Endpoint=address+"/cancel",ApiKey="dummy"};using var stop=new CancellationTokenSource(100);try{await new HttpTranslationProvider(c,client).TranslateAsync(new(1,"c",1,Source,"en","zh",[]),stop.Token);throw new Exception("expected cancellation");}catch(OperationCanceledException){Assert(stop.IsCancellationRequested,"caller cancellation");}});
        await Check("server protocol assertions",()=>{Assert(errors.IsEmpty,string.Join("; ",errors));Assert(wavs==8&&writes>0&&sockets==3&&finalFrames==3,"protocol counts");return Task.CompletedTask;});await app.StopAsync();Directory.CreateDirectory("artifacts/phase4");var report=new{scope="real localhost HTTP/multipart/Volc binary WebSocket; SDK injected HTTP gateway fixtures, not native Azure/gRPC wire; dummy keys; finite synthetic PCM16kmono",total=checks.Count,failed,combinations=15,wavs,writes,sockets,finalFrames,checks};await File.WriteAllTextAsync("artifacts/phase4/combinations.json",JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(report));return failed==0?0:1;
    }
    static async Task<byte[]> Receive(WebSocket ws,CancellationToken token){using var data=new MemoryStream();var bytes=new byte[8192];WebSocketReceiveResult part;do{part=await ws.ReceiveAsync(bytes,token);data.Write(bytes,0,part.Count);}while(!part.EndOfMessage);return data.ToArray();}
    static Task Send(WebSocket ws,bool final,bool terminal,CancellationToken token){var json=JsonSerializer.SerializeToUtf8Bytes(new{result=new{utterances=new[]{new{start_time=0,end_time=300,text=Source,definite=final}}}});var bytes=new byte[12+json.Length];bytes[0]=0x11;bytes[1]=(byte)(terminal?0x93:0x91);bytes[2]=0x10;BinaryPrimitives.WriteInt32BigEndian(bytes.AsSpan(4),terminal?-1:1);BinaryPrimitives.WriteInt32BigEndian(bytes.AsSpan(8),json.Length);json.CopyTo(bytes,12);return ws.SendAsync(bytes,WebSocketMessageType.Binary,true,token);}
    sealed class Gateway(HttpClient client,string address):ISpeechTransport{
        bool emitted;public bool Disposed;public event Action<SpeechEvent>? Result;public event Action<ProviderErrorKind>? Failed { add { } remove { } }public event Action? Stopped;
        public async Task StartAsync(CancellationToken token){using var r=await client.PostAsync(address+"/gateway/start",new ByteArrayContent([]),token);r.EnsureSuccessStatusCode();}
        public async Task WriteAsync(ReadOnlyMemory<byte> pcm,CancellationToken token){using var r=await client.PostAsync(address+"/gateway/write",new ByteArrayContent(pcm.ToArray()),token);r.EnsureSuccessStatusCode();var json=await r.Content.ReadFromJsonAsync<JsonElement>(token);if(!emitted&&pcm.Span.Contains((byte)16)){emitted=true;Result?.Invoke(new(json.GetProperty("text").GetString()!,false,TimeSpan.Zero,TimeSpan.FromMilliseconds(300),"en-US"));}}
        public async Task CompleteAsync(CancellationToken token){using var r=await client.PostAsync(address+"/gateway/complete",new ByteArrayContent([]),token);r.EnsureSuccessStatusCode();var json=await r.Content.ReadFromJsonAsync<JsonElement>(token);Result?.Invoke(new(json.GetProperty("text").GetString()!,true,TimeSpan.Zero,TimeSpan.FromMilliseconds(300),"en-US"));Stopped?.Invoke();}public ValueTask DisposeAsync(){Disposed=true;return ValueTask.CompletedTask;}}
    sealed class Audio:IAudioSource{public bool Disposed;public string Name=>"finite synthetic PCM16kmono";public Task StartAsync(CancellationToken t)=>Task.CompletedTask;public Task StopAsync(CancellationToken t)=>Task.CompletedTask;public async IAsyncEnumerable<AudioChunk> ReadChunksAsync([EnumeratorCancellation] CancellationToken t){for(int i=0;i<6;i++){var pcm=new byte[3200];if(i<3)for(int j=1;j<pcm.Length;j+=2)pcm[j]=16;yield return new(pcm,TimeSpan.FromMilliseconds(i*100),TimeSpan.FromMilliseconds(100),Stopwatch.GetTimestamp());await Task.Delay(20,t);}}public ValueTask DisposeAsync(){Disposed=true;return ValueTask.CompletedTask;}}
}


